// Normaliza fontes diferentes num formato só e pontua contra o perfil.
//
// A primeira versão usava booleano — "bateu numa palavra, entra" — e deixou
// passar Frontend, Ruby on Rails e Applied AI. O motivo: numa descrição de
// 4 mil caracteres, "backend" ou "typescript" aparece em quase toda vaga de
// engenharia. Palavra solta em texto longo não é sinal.
//
// Agora cada indício vale pontos, e o TÍTULO pesa muito mais que o corpo:
// o que a empresa põe no título é o que a vaga é; o resto é contexto.

// Calibrado pelo currículo: 5 anos em mercado financeiro, C#/.NET com
// arquitetura event-driven, mensageria e observabilidade.
const NUCLEO = /\b(\.net|dotnet|c#|csharp|asp\.net|entity framework)\b/i;
const ARQUITETURA = /\b(microservi|micro-servi|event[- ]driven|ddd|cqrs|hexagonal|clean architecture)\b/i;
const MENSAGERIA = /\b(kafka|rabbitmq|sqs|service bus|event hub)\b/i;
const DOMINIO = /\b(fintech|payment|pagament|banking|banco|financial|trading|chargeback|risk|credit)\b/i;
const NUVEM = /\b(aws|azure|kubernetes|docker)\b/i;

// Stacks que EXCLUEM: se o título é de outra linguagem, a vaga não é dele por
// mais que a descrição cite ".NET" numa lista de "diferenciais".
const OUTRA_STACK = /\b(ruby|rails|golang|\bgo\b|rust|scala|elixir|django|laravel|php|salesforce|sap|abap)\b/i;
const NAO_ENGENHARIA = /\b(recruit|sales|marketing|designer|support|assistant|writer|blog|newsletter|customer success|frontend|front[- ]end|mobile|ios|android|data scientist|ml engineer)\b/i;

const JUNIOR = /\b(junior|jr\.?|intern|internship|trainee|apprentice|estági)\b/i;
const SENIOR = /\b(senior|sr\.?|staff|principal|lead|architect|especialista)\b/i;
const PLENO = /\b(pleno|mid[- ]?level|mid[- ]?senior)\b/i;

function senioridade(titulo) {
  if (JUNIOR.test(titulo)) return 'outro';
  if (SENIOR.test(titulo)) return 'senior';
  if (PLENO.test(titulo)) return 'pleno';
  return 'pleno';
}

function limpar(html) {
  return String(html || '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 4000);
}

/** Pontua a aderência ao perfil. O corte exige mais que uma coincidência. */
function pontuar(v) {
  const t = v.title || '';
  const d = v.description || '';

  // Barreiras: nenhuma pontuação salva uma vaga de outra área.
  if (NAO_ENGENHARIA.test(t)) return 0;
  if (OUTRA_STACK.test(t) && !NUCLEO.test(t)) return 0;
  if (!/\b(engineer|developer|desenvolvedor|programador|engenheiro)\b/i.test(t)) return 0;

  let p = 0;
  if (NUCLEO.test(t)) p += 60;        // .NET no título: é a vaga dele
  else if (NUCLEO.test(d)) p += 25;   // só na descrição: pode ser "diferencial"
  if (DOMINIO.test(t)) p += 15;
  else if (DOMINIO.test(d)) p += 8;
  if (ARQUITETURA.test(d)) p += 8;
  if (MENSAGERIA.test(d)) p += 8;
  if (NUVEM.test(d)) p += 4;
  return p;
}

/** Abaixo disto não vale a chamada de pontuação do modelo. */
const CORTE = 30;

const vagas = [];

for (const item of $input.all()) {
  const d = item.json;

  for (const j of d.jobs || []) {
    vagas.push({
      source: 'remotive', sourceId: String(j.id), url: j.url, title: j.title,
      company: j.company_name, location: j.candidate_required_location, workMode: 'remoto',
      salaryText: j.salary || undefined, description: limpar(j.description),
      postedAt: j.publication_date,
    });
  }

  for (const j of d.data || []) {
    vagas.push({
      source: 'arbeitnow', sourceId: j.slug, url: j.url, title: j.title,
      company: j.company_name, location: j.location,
      workMode: j.remote ? 'remoto' : undefined, description: limpar(j.description),
      postedAt: j.created_at ? new Date(j.created_at * 1000).toISOString() : undefined,
    });
  }
}

const aprovadas = [];
for (const v of vagas) {
  const p = pontuar(v);
  if (p < CORTE) continue;
  v.seniority = senioridade(v.title);
  if (v.seniority !== 'pleno' && v.seniority !== 'senior') continue;
  // Nota de triagem, não a do ALAN: ele repontua depois com o currículo inteiro.
  v.preScore = p;
  aprovadas.push(v);
}

aprovadas.sort((a, b) => b.preScore - a.preScore);

return [{ json: { jobs: aprovadas, coletadas: vagas.length, aproveitadas: aprovadas.length } }];
